// 🔄 Auto Recovery - Week 4
// Circuit Breaker, Timeout Standardization, Retry Strategy

/**
 * CircuitBreakerState: Circuit Breaker 상태
 * CLOSED: 정상 작동 (요청 통과)
 * OPEN: 장애 감지 (요청 차단)
 * HALF_OPEN: 복구 테스트 (제한된 요청 통과)
 */
export enum CircuitBreakerState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN',
}

/**
 * CircuitBreakerConfig: Circuit Breaker 설정
 */
export interface CircuitBreakerConfig {
  failureThreshold: number;           // 실패 횟수 임계값 (기본 5)
  successThreshold: number;           // Half-Open에서 성공 임계값 (기본 2)
  timeout: number;                    // Open → Half-Open 전환 시간(ms) (기본 10s)
  monitoringWindow: number;           // 실패 모니터링 윈도우(ms) (기본 60s)
}

/**
 * CircuitBreakerMetrics: Circuit Breaker 메트릭
 */
export interface CircuitBreakerMetrics {
  state: CircuitBreakerState;
  failureCount: number;               // 현재 실패 횟수
  successCount: number;               // Half-Open에서 성공 횟수
  totalFailures: number;              // 누적 실패
  totalSuccesses: number;             // 누적 성공
  stateTransitions: number;           // 상태 전환 횟수
  lastStateChange: bigint;            // 마지막 상태 변경 시각
  openedAt?: bigint;                  // Open 시각
  halfOpenAt?: bigint;                // Half-Open 시각
}

/**
 * CircuitBreaker: Circuit Breaker 패턴 구현
 *
 * 역할:
 * 1. CLOSED: 요청 정상 처리
 * 2. 실패 임계값 도달 → OPEN으로 전환
 * 3. OPEN: 요청 즉시 차단 (fail-fast)
 * 4. Timeout 후 HALF_OPEN으로 전환
 * 5. HALF_OPEN: 제한된 요청으로 복구 테스트
 * 6. 성공 임계값 도달 → CLOSED로 복구
 */
export class CircuitBreaker {
  private state: CircuitBreakerState = CircuitBreakerState.CLOSED;
  private failureCount: number = 0;
  private successCount: number = 0;
  private totalFailures: number = 0;
  private totalSuccesses: number = 0;
  private stateTransitions: number = 0;
  private lastStateChange: bigint = BigInt(Date.now());
  private openedAt?: bigint;
  private halfOpenAt?: bigint;
  private failureTimestamps: bigint[] = [];

  constructor(private config: CircuitBreakerConfig) {
    // 기본값 설정
    if (!this.config.failureThreshold) this.config.failureThreshold = 5;
    if (!this.config.successThreshold) this.config.successThreshold = 2;
    if (!this.config.timeout) this.config.timeout = 10000; // 10초
    if (!this.config.monitoringWindow) this.config.monitoringWindow = 60000; // 60초
  }

  /**
   * 요청 실행 시도
   * @param operation 실행할 작업
   * @returns 작업 결과
   */
  public async execute<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    // OPEN 상태일 때 즉시 실패
    if (this.state === CircuitBreakerState.OPEN) {
      // Open 시간 초과 확인
      if (this.openedAt) {
        const now = BigInt(Date.now());
        const elapsedMs = Number(now - this.openedAt);
        if (elapsedMs >= this.config.timeout) {
          this.transitionToHalfOpen();
        } else {
          throw new Error(
            `Circuit breaker is OPEN. Retry after ${this.config.timeout - elapsedMs}ms`
          );
        }
      }
    }

    // 작업 실행
    try {
      const result = await operation();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }

  /**
   * 성공 기록
   */
  private recordSuccess(): void {
    this.totalSuccesses++;

    if (this.state === CircuitBreakerState.HALF_OPEN) {
      this.successCount++;
      if (this.successCount >= this.config.successThreshold) {
        this.transitionToClosed();
      }
    } else if (this.state === CircuitBreakerState.CLOSED) {
      // 정상 상태 유지, 실패 카운트 리셋 (모니터링 윈도우 기반)
      this.cleanupOldFailures();
    }
  }

  /**
   * 실패 기록
   */
  private recordFailure(): void {
    this.totalFailures++;
    this.failureTimestamps.push(BigInt(Date.now()));

    if (this.state === CircuitBreakerState.HALF_OPEN) {
      // Half-Open 상태에서 실패 → OPEN으로 복귀
      this.transitionToOpen();
    } else if (this.state === CircuitBreakerState.CLOSED) {
      this.failureCount++;
      if (this.failureCount >= this.config.failureThreshold) {
        this.transitionToOpen();
      }
    }
  }

  /**
   * CLOSED로 전환
   */
  private transitionToClosed(): void {
    this.state = CircuitBreakerState.CLOSED;
    this.failureCount = 0;
    this.successCount = 0;
    this.stateTransitions++;
    this.lastStateChange = BigInt(Date.now());
    this.failureTimestamps = [];
  }

  /**
   * OPEN으로 전환
   */
  private transitionToOpen(): void {
    this.state = CircuitBreakerState.OPEN;
    this.openedAt = BigInt(Date.now());
    this.successCount = 0;
    this.stateTransitions++;
    this.lastStateChange = BigInt(Date.now());
  }

  /**
   * HALF_OPEN으로 전환
   */
  private transitionToHalfOpen(): void {
    this.state = CircuitBreakerState.HALF_OPEN;
    this.halfOpenAt = BigInt(Date.now());
    this.failureCount = 0;
    this.successCount = 0;
    this.stateTransitions++;
    this.lastStateChange = BigInt(Date.now());
  }

  /**
   * 모니터링 윈도우 외 오래된 실패 제거
   */
  private cleanupOldFailures(): void {
    const now = BigInt(Date.now());
    const windowStartTime = now - BigInt(this.config.monitoringWindow);

    this.failureTimestamps = this.failureTimestamps.filter(
      (ts) => ts >= windowStartTime
    );
    this.failureCount = this.failureTimestamps.length;
  }

  /**
   * 메트릭 조회
   */
  public getMetrics(): CircuitBreakerMetrics {
    return {
      state: this.state,
      failureCount: this.failureCount,
      successCount: this.successCount,
      totalFailures: this.totalFailures,
      totalSuccesses: this.totalSuccesses,
      stateTransitions: this.stateTransitions,
      lastStateChange: this.lastStateChange,
      openedAt: this.openedAt,
      halfOpenAt: this.halfOpenAt,
    };
  }
}

/**
