export interface TimeoutPolicy {
  defaultTimeoutMs: number;           // 기본 타임아웃(ms)
  rdmaOperationTimeoutMs: number;     // RDMA 작업 타임아웃
  semanticSyncTimeoutMs: number;      // Semantic Sync 타임아웃
  healthCheckTimeoutMs: number;       // 헬스 체크 타임아웃
}

/**
 * TimeoutManager: 타임아웃 표준화
 *
 * 역할:
 * - 통일된 타임아웃 정책 제공
 * - 작업별 타임아웃 설정
 * - 타임아웃 초과 감지
 */
export class TimeoutManager {
  private readonly policy: TimeoutPolicy;

  constructor(policy?: Partial<TimeoutPolicy>) {
    this.policy = {
      defaultTimeoutMs: policy?.defaultTimeoutMs ?? 5000,
      rdmaOperationTimeoutMs: policy?.rdmaOperationTimeoutMs ?? 3000,
      semanticSyncTimeoutMs: policy?.semanticSyncTimeoutMs ?? 7000,
      healthCheckTimeoutMs: policy?.healthCheckTimeoutMs ?? 2000,
    };
  }

  /**
   * 타임아웃이 있는 작업 실행
   * @param operation 실행할 작업
   * @param timeoutMs 타임아웃(ms), 기본값: defaultTimeoutMs
   * @returns 작업 결과
   */
  public async executeWithTimeout<T>(
    operation: () => Promise<T>,
    timeoutMs?: number
  ): Promise<T> {
    const timeout = timeoutMs ?? this.policy.defaultTimeoutMs;

    return Promise.race([
      operation(),
      new Promise<T>((_, reject) =>
        setTimeout(
          () => reject(new Error(`Operation timeout after ${timeout}ms`)),
          timeout
        )
      ),
    ]);
  }

  /**
   * RDMA 작업 타임아웃 실행
   */
  public async executeRDMAWithTimeout<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.executeWithTimeout(operation, this.policy.rdmaOperationTimeoutMs);
  }

  /**
   * Semantic Sync 타임아웃 실행
   */
  public async executeSyncWithTimeout<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.executeWithTimeout(operation, this.policy.semanticSyncTimeoutMs);
  }

  /**
   * 헬스 체크 타임아웃 실행
   */
  public async executeHealthCheckWithTimeout<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.executeWithTimeout(operation, this.policy.healthCheckTimeoutMs);
  }

  /**
   * 타임아웃 정책 조회
   */
  public getPolicy(): TimeoutPolicy {
    return { ...this.policy };
  }
}

/**
 * AutoRecoveryOrchestrator: 자동 복구 오케스트레이터
 *
 * Circuit Breaker + Retry Strategy + Timeout Manager를 조합
 */
export class AutoRecoveryOrchestrator {
  private circuitBreaker: CircuitBreaker;
  private retryStrategy: RetryStrategy;
  private timeoutManager: TimeoutManager;

  constructor(
    circuitBreakerConfig?: CircuitBreakerConfig,
    retryPolicy?: RetryPolicy,
    timeoutPolicy?: Partial<TimeoutPolicy>
  ) {
    this.circuitBreaker = new CircuitBreaker(
      circuitBreakerConfig ?? {
        failureThreshold: 5,
        successThreshold: 2,
        timeout: 10000,
        monitoringWindow: 60000,
      }
    );

    this.retryStrategy = new RetryStrategy(
      retryPolicy ?? {
        maxRetries: 3,
        initialDelayMs: 100,
        maxDelayMs: 10000,
        backoffMultiplier: 2,
        jitterFactor: 0.1,
      }
    );

    this.timeoutManager = new TimeoutManager(timeoutPolicy);
  }

  /**
   * 완전한 복구 메커니즘으로 작업 실행
   * 1. Circuit Breaker 확인
   * 2. 재시도 with 지수 백오프
   * 3. 타임아웃 보호
   */
  public async executeWithFullRecovery<T>(
    operation: () => Promise<T>,
    timeoutMs?: number
  ): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      return this.retryStrategy.execute(async () => {
        return this.timeoutManager.executeWithTimeout(operation, timeoutMs);
      });
    });
  }

  /**
   * RDMA 작업 전용
   */
  public async executeRDMAWithRecovery<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      return this.retryStrategy.execute(async () => {
        return this.timeoutManager.executeRDMAWithTimeout(operation);
      });
    });
  }

  /**
   * Semantic Sync 작업 전용
   */
  public async executeSyncWithRecovery<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      return this.retryStrategy.execute(async () => {
        return this.timeoutManager.executeSyncWithTimeout(operation);
      });
    });
  }

  /**
   * 상태 조회
   */
  public getStatus(): {
    circuitBreaker: CircuitBreakerMetrics;
    retryCount: number;
    timeoutPolicy: TimeoutPolicy;
  } {
    return {
      circuitBreaker: this.circuitBreaker.getMetrics(),
      retryCount: this.retryStrategy.getRetryCount(),
      timeoutPolicy: this.timeoutManager.getPolicy(),
    };
  }

  /**
   * 상태 리셋
   */
  public reset(): void {
    this.circuitBreaker = new CircuitBreaker(
      this.circuitBreaker.getMetrics() as any
    );
  }
}

