/**
 * Test 16: Circuit Breaker - Basic State Transitions
 * Week 4: Auto-Recovery Mechanisms
 */
async function testCircuitBreakerStateTransitions(): Promise<void> {
  console.log(
    `\n${colors.blue}[TEST 16] Circuit Breaker - State Transitions${colors.reset}`
  );

  const breaker = new CircuitBreaker({
    failureThreshold: 3,
    successThreshold: 2,
    timeout: 1000,
    monitoringWindow: 60000,
  });

  // 초기 상태: CLOSED
  let metrics = breaker.getMetrics();
  assert(metrics.state === CircuitBreakerState.CLOSED, 'Initial state should be CLOSED');

  // 3번 실패 → OPEN 전환
  for (let i = 0; i < 3; i++) {
    try {
      await breaker.execute(async () => {
        throw new Error('Intentional failure');
      });
    } catch (e) {
      // Expected failures
    }
  }

  metrics = breaker.getMetrics();
  assert(metrics.state === CircuitBreakerState.OPEN, 'Should transition to OPEN after failures');
  assert(metrics.failureCount === 3, 'Should have 3 failures');
  assert(metrics.stateTransitions === 1, 'Should have 1 state transition');

  // OPEN 상태에서 요청 차단
  try {
    await breaker.execute(async () => 'success');
    assert(false, 'Should reject when OPEN');
  } catch (e) {
    assert(true, 'Circuit breaker should reject in OPEN state');
  }

  console.log(`    State transitions: ${metrics.stateTransitions}`);
  console.log(`    Failure count: ${metrics.failureCount}`);
}

/**
 * Test 17: Circuit Breaker - Recovery to CLOSED
 */
async function testCircuitBreakerRecovery(): Promise<void> {
  console.log(
    `\n${colors.blue}[TEST 17] Circuit Breaker - Recovery to CLOSED${colors.reset}`
  );

  const breaker = new CircuitBreaker({
    failureThreshold: 2,
    successThreshold: 2,
    timeout: 500,
    monitoringWindow: 60000,
  });

  // 2번 실패 → OPEN
  for (let i = 0; i < 2; i++) {
    try {
      await breaker.execute(async () => {
        throw new Error('Failure');
      });
    } catch (e) {
      // Expected
    }
  }

  let metrics = breaker.getMetrics();
  assert(metrics.state === CircuitBreakerState.OPEN, 'Should be OPEN');

  // Timeout 후 HALF_OPEN 자동 전환
  await new Promise((r) => setTimeout(r, 600));

  // HALF_OPEN에서 성공 → CLOSED 복구
  for (let i = 0; i < 2; i++) {
    await breaker.execute(async () => 'success');
  }

  metrics = breaker.getMetrics();
  assert(metrics.state === CircuitBreakerState.CLOSED, 'Should recover to CLOSED');
  assert(metrics.stateTransitions === 3, 'Should have 3 transitions (CLOSED→OPEN→HALF→CLOSED)');

  console.log(`    Recovery successful: ${metrics.state}`);
  console.log(`    Total transitions: ${metrics.stateTransitions}`);
}

/**
 * Test 18: Retry Strategy - Exponential Backoff
 */
async function testRetryStrategyBackoff(): Promise<void> {
  console.log(
    `\n${colors.blue}[TEST 18] Retry Strategy - Exponential Backoff${colors.reset}`
  );

  const strategy = new RetryStrategy({
    maxRetries: 3,
    initialDelayMs: 100,
    maxDelayMs: 5000,
    backoffMultiplier: 2,
    jitterFactor: 0,
  });

  let attemptCount = 0;
  const startTime = Date.now();

  try {
    await strategy.execute(async () => {
      attemptCount++;
      if (attemptCount < 4) {
        throw new Error('Retry me');
      }
      return 'success';
    });
  } catch (e) {
    // Not expected
  }

  const elapsedMs = Date.now() - startTime;

  // 지연: 100ms + 200ms + 400ms = 700ms (최소)
  assert(attemptCount === 4, 'Should retry until success');
  assert(strategy.getRetryCount() === 3, 'Should have 3 retries');
  assert(elapsedMs >= 700, `Should have cumulative delay, got ${elapsedMs}ms`);

  console.log(`    Attempts: ${attemptCount}`);
  console.log(`    Retry count: ${strategy.getRetryCount()}`);
  console.log(`    Elapsed time: ${elapsedMs}ms`);
}

/**
 * Test 19: Timeout Manager - Operation Timeout
 */
async function testTimeoutManager(): Promise<void> {
  console.log(
    `\n${colors.blue}[TEST 19] Timeout Manager - Operation Timeout${colors.reset}`
  );

  const manager = new TimeoutManager({
    defaultTimeoutMs: 100,
    rdmaOperationTimeoutMs: 200,
    semanticSyncTimeoutMs: 500,
    healthCheckTimeoutMs: 50,
  });

  // 성공: 빠른 작업
  const result = await manager.executeWithTimeout(
    async () => 'success',
    50
  );
  assert(result === 'success', 'Fast operation should succeed');

  // 실패: 느린 작업
  try {
    await manager.executeWithTimeout(
      async () => {
        await new Promise((r) => setTimeout(r, 200));
        return 'too slow';
      },
      50
    );
    assert(false, 'Should timeout');
  } catch (e) {
    assert(true, 'Timeout should trigger');
  }

  // 정책별 타임아웃
  const policy = manager.getPolicy();
  assert(policy.healthCheckTimeoutMs === 50, 'Health check timeout should be 50ms');

  console.log(`    Health check timeout: ${policy.healthCheckTimeoutMs}ms`);
  console.log(`    RDMA operation timeout: ${policy.rdmaOperationTimeoutMs}ms`);
}

/**
 * Test 20: Auto-Recovery Orchestrator - Full Integration
 */
async function testAutoRecoveryOrchestrator(): Promise<void> {
  console.log(
    `\n${colors.blue}[TEST 20] Auto-Recovery Orchestrator - Full Integration${colors.reset}`
  );

  const orchestrator = new AutoRecoveryOrchestrator(
    {
      failureThreshold: 2,
      successThreshold: 1,
      timeout: 500,
      monitoringWindow: 60000,
    },
    {
      maxRetries: 2,
      initialDelayMs: 50,
      maxDelayMs: 1000,
      backoffMultiplier: 2,
      jitterFactor: 0.1,
    },
    {
      defaultTimeoutMs: 5000,
      rdmaOperationTimeoutMs: 3000,
    }
  );

  let attemptCount = 0;

  // 복구 불가능한 작업
  try {
    await orchestrator.executeWithFullRecovery(async () => {
      attemptCount++;
      throw new Error('Always fail');
    });
    assert(false, 'Should fail after all retries');
  } catch (e) {
    assert(true, 'Should exhaust retries');
  }

  let status = orchestrator.getStatus();
  assert(status.circuitBreaker.totalFailures > 0, 'Should record failures');

  // 복구 가능한 작업
  attemptCount = 0;
  const result = await orchestrator.executeWithFullRecovery(async () => {
    attemptCount++;
    if (attemptCount < 2) throw new Error('Retry');
    return 'success';
  });

  assert(result === 'success', 'Should succeed after retry');
  assert(attemptCount === 2, 'Should require 2 attempts');

  status = orchestrator.getStatus();
  console.log(`    Circuit breaker state: ${status.circuitBreaker.state}`);
  console.log(`    Total failures: ${status.circuitBreaker.totalFailures}`);
  console.log(`    Retry count: ${status.retryCount}`);
}

/**
 * 모든 테스트 실행
 */
async function runAllTests(): Promise<void> {
  console.log(`
╔════════════════════════════════════════════════════════════╗
║ 🌐 Global Synapse Engine - Phase 1 Tests                    ║
║ Layer 1: Inter-Node Fabric (RDMA)                          ║
║ Layer 2: Semantic Sync Protocol                            ║
║ Week 2: Real Performance Measurement                       ║
╚════════════════════════════════════════════════════════════╝
  `);

  // 메모리 프로파일링 시작
  const profiler = getGlobalProfiler();
  profiler.start();

  const startTime = Date.now();

  try {
    await testHashChainIntegrity();
    await testLargeHashChain();
    await testRDMAFabricZeroCopy();
    await testRDMAOperationsWithLog();
    await testSemanticSyncDeterministic();
    await testSemanticEquivalenceProof();
    await testGlobalSemanticConsistency();
    await testSyncLogIntegrity();
    await testLayer1Layer2Integration();
    await testUnforgivingRules();

    // Week 3: Chaos Testing
    await testChaosNetworkDelay();
    await testChaosPacketLoss();
    await testChaosNodeCrash();
    await testChaosMemorySpike();
    await testChaosScenario();

    // Week 4: Auto-Recovery Mechanisms
    await testCircuitBreakerStateTransitions();
    await testCircuitBreakerRecovery();
    await testRetryStrategyBackoff();
    await testTimeoutManager();
    await testAutoRecoveryOrchestrator();
  } catch (error) {
    console.log(`\n${colors.red}ERROR: ${error}${colors.reset}`);
    if (error instanceof Error) {
      console.log(`Stack: ${error.stack}`);
    }
    testsFailed++;
  }

  const elapsedMs = Date.now() - startTime;
  profiler.stop();

  // 성능 모니터 리포트
  const monitor = getGlobalMonitor();
  monitor.printReport();

  // 메모리 프로파일 리포트
  const memoryReport = profiler.analyzeTrend();
  profiler.printReport();

  // 결과 요약
  console.log(`
╔════════════════════════════════════════════════════════════╗
║ Test Results                                               ║
╚════════════════════════════════════════════════════════════╝
${colors.green}✅ Passed: ${testsPassed}${colors.reset}
${colors.red}❌ Failed: ${testsFailed}${colors.reset}
⏱️  Total Time: ${elapsedMs}ms
Pass Rate: ${((testsPassed / (testsPassed + testsFailed)) * 100).toFixed(1)}%

${testsFailed === 0 ? `${colors.green}🎉 ALL TESTS PASSED!${colors.reset}` : `${colors.red}⚠️  SOME TESTS FAILED${colors.reset}`}

💾 Memory Report:
   Leak Status: ${memoryReport.isLeaking ? '⚠️  LEAKING' : '✅ OK'}
  `);
}

// 메인 실행
runAllTests().catch((err) => {
  console.error('Fatal error:', err);
  process.exit(1);
});

