  failureThreshold: number;           // 실패 횟수 임계값 (기본 5)
  successThreshold: number;           // Half-Open에서 성공 임계값 (기본 2)
  timeout: number;                    // Open → Half-Open 전환 시간(ms) (기본 10s)
  monitoringWindow: number;           // 실패 모니터링 윈도우(ms) (기본 60s)
}

/**
 * CircuitBreakerMetrics: Circuit Breaker 메트릭
 */
export interface CircuitBreakerMetrics {
  state: CircuitBreakerState;
  failureCount: number;               // 현재 실패 횟수
  successCount: number;               // Half-Open에서 성공 횟수
  totalFailures: number;              // 누적 실패
  totalSuccesses: number;             // 누적 성공
  stateTransitions: number;           // 상태 전환 횟수
  lastStateChange: bigint;            // 마지막 상태 변경 시각
  openedAt?: bigint;                  // Open 시각
  halfOpenAt?: bigint;                // Half-Open 시각
}

/**
 * CircuitBreaker: Circuit Breaker 패턴 구현
 *
 * 역할:
 * 1. CLOSED: 요청 정상 처리
 * 2. 실패 임계값 도달 → OPEN으로 전환
 * 3. OPEN: 요청 즉시 차단 (fail-fast)
 * 4. Timeout 후 HALF_OPEN으로 전환
 * 5. HALF_OPEN: 제한된 요청으로 복구 테스트
 * 6. 성공 임계값 도달 → CLOSED로 복구
 */
export class CircuitBreaker {
  private state: CircuitBreakerState = CircuitBreakerState.CLOSED;
  private failureCount: number = 0;
  private successCount: number = 0;
  private totalFailures: number = 0;
  private totalSuccesses: number = 0;
  private stateTransitions: number = 0;
  private lastStateChange: bigint = BigInt(Date.now());
  private openedAt?: bigint;
  private halfOpenAt?: bigint;
  private failureTimestamps: bigint[] = [];

  constructor(private config: CircuitBreakerConfig) {
    // 기본값 설정
    if (!this.config.failureThreshold) this.config.failureThreshold = 5;
    if (!this.config.successThreshold) this.config.successThreshold = 2;
    if (!this.config.timeout) this.config.timeout = 10000; // 10초
    if (!this.config.monitoringWindow) this.config.monitoringWindow = 60000; // 60초
  }

  /**
   * 요청 실행 시도
   * @param operation 실행할 작업
   * @returns 작업 결과
   */
  public async execute<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    // OPEN 상태일 때 즉시 실패
    if (this.state === CircuitBreakerState.OPEN) {
      // Open 시간 초과 확인
      if (this.openedAt) {
        const now = BigInt(Date.now());
        const elapsedMs = Number(now - this.openedAt);
        if (elapsedMs >= this.config.timeout) {
          this.transitionToHalfOpen();
        } else {
          throw new Error(
            `Circuit breaker is OPEN. Retry after ${this.config.timeout - elapsedMs}ms`
          );
        }
      }
    }

    // 작업 실행
    try {
      const result = await operation();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }

  /**
   * 성공 기록
   */
  private recordSuccess(): void {
    this.totalSuccesses++;

    if (this.state === CircuitBreakerState.HALF_OPEN) {
      this.successCount++;
      if (this.successCount >= this.config.successThreshold) {
        this.transitionToClosed();
      }
    } else if (this.state === CircuitBreakerState.CLOSED) {
      // 정상 상태 유지, 실패 카운트 리셋 (모니터링 윈도우 기반)
      this.cleanupOldFailures();
    }
  }

  /**
   * 실패 기록
   */
  private recordFailure(): void {
    this.totalFailures++;
    this.failureTimestamps.push(BigInt(Date.now()));

    if (this.state === CircuitBreakerState.HALF_OPEN) {
      // Half-Open 상태에서 실패 → OPEN으로 복귀
      this.transitionToOpen();
    } else if (this.state === CircuitBreakerState.CLOSED) {
      this.failureCount++;
      if (this.failureCount >= this.config.failureThreshold) {
        this.transitionToOpen();
      }
    }
  }

  /**
   * CLOSED로 전환
   */
  private transitionToClosed(): void {
    this.state = CircuitBreakerState.CLOSED;
    this.failureCount = 0;
    this.successCount = 0;
    this.stateTransitions++;
    this.lastStateChange = BigInt(Date.now());
    this.failureTimestamps = [];
  }

  /**
   * OPEN으로 전환
   */
  private transitionToOpen(): void {
    this.state = CircuitBreakerState.OPEN;
    this.openedAt = BigInt(Date.now());
    this.successCount = 0;
    this.stateTransitions++;
    this.lastStateChange = BigInt(Date.now());
  }

  /**
   * HALF_OPEN으로 전환
   */
  private transitionToHalfOpen(): void {
    this.state = CircuitBreakerState.HALF_OPEN;
    this.halfOpenAt = BigInt(Date.now());
    this.failureCount = 0;
    this.successCount = 0;
    this.stateTransitions++;
    this.lastStateChange = BigInt(Date.now());
  }

  /**
   * 모니터링 윈도우 외 오래된 실패 제거
   */
  private cleanupOldFailures(): void {
    const now = BigInt(Date.now());
    const windowStartTime = now - BigInt(this.config.monitoringWindow);

    this.failureTimestamps = this.failureTimestamps.filter(
      (ts) => ts >= windowStartTime
    );
    this.failureCount = this.failureTimestamps.length;
  }

  /**
   * 메트릭 조회
   */
  public getMetrics(): CircuitBreakerMetrics {
    return {
      state: this.state,
      failureCount: this.failureCount,
      successCount: this.successCount,
      totalFailures: this.totalFailures,
      totalSuccesses: this.totalSuccesses,
      stateTransitions: this.stateTransitions,
      lastStateChange: this.lastStateChange,
      openedAt: this.openedAt,
      halfOpenAt: this.halfOpenAt,
    };
  }
}

/**
 * RetryPolicy: 재시도 정책
 */
export interface RetryPolicy {
  maxRetries: number;                 // 최대 재시도 횟수
  initialDelayMs: number;             // 초기 지연(ms)
  maxDelayMs: number;                 // 최대 지연(ms)
  backoffMultiplier: number;          // 지수 백오프 배수
  jitterFactor: number;               // 지터 비율 (0.0-1.0)
}

/**
 * RetryStrategy: 재시도 전략 (지수 백오프 + 지터)
 *
 * 계산식:
 * delay = min(initialDelayMs * (backoffMultiplier ^ attempt), maxDelayMs)
 * delay = delay * (1 + random(-jitterFactor, +jitterFactor))
 */
export class RetryStrategy {
  private retryCount: number = 0;
  private lastDelayMs: number = 0;
  private lastAttemptCount: number = 0;

  constructor(private policy: RetryPolicy) {
    // 기본값 설정
    if (!this.policy.maxRetries) this.policy.maxRetries = 3;
    if (!this.policy.initialDelayMs) this.policy.initialDelayMs = 100;
    if (!this.policy.maxDelayMs) this.policy.maxDelayMs = 10000;
    if (!this.policy.backoffMultiplier) this.policy.backoffMultiplier = 2;
    if (this.policy.jitterFactor === undefined) this.policy.jitterFactor = 0.1;
  }

  /**
   * 작업 실행 with 재시도
   * @param operation 실행할 작업
   * @returns 작업 결과
   */
  public async execute<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    let lastError: Error | null = null;
    this.lastAttemptCount = 0;

    for (let attempt = 0; attempt <= this.policy.maxRetries; attempt++) {
      this.lastAttemptCount++;
      try {
        const result = await operation();
        // 성공 시에만 retryCount를 업데이트 (정보 유지)
        this.retryCount = attempt > 0 ? attempt - 1 : 0;
        return result;
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));

        if (attempt < this.policy.maxRetries) {
          // 재시도 대기
          const delayMs = this.calculateDelay(attempt);
          await new Promise((resolve) => setTimeout(resolve, delayMs));
          this.retryCount = attempt;
        }
      }
    }

    // 모든 재시도 실패 시 최종 재시도 횟수 기록
    this.retryCount = this.policy.maxRetries;
    throw lastError || new Error('Operation failed after all retries');
  }

  /**
   * 지수 백오프 + 지터 지연 계산
   */
  private calculateDelay(attempt: number): number {
    // 지수 백오프
    let delay = Math.min(
      this.policy.initialDelayMs * Math.pow(this.policy.backoffMultiplier, attempt),
      this.policy.maxDelayMs
    );

    // 지터 추가
    const jitterRange = delay * this.policy.jitterFactor;
    const jitter = (Math.random() - 0.5) * 2 * jitterRange;
    delay = Math.max(0, delay + jitter);

    this.lastDelayMs = delay;
    return Math.floor(delay);
  }

  /**
   * 재시도 횟수 조회
   */
  public getRetryCount(): number {
    return this.retryCount;
  }

  /**
   * 마지막 지연 조회
   */
  public getLastDelayMs(): number {
    return this.lastDelayMs;
  }
}

/**
 * TimeoutPolicy: 타임아웃 정책
 */
export interface TimeoutPolicy {
  defaultTimeoutMs: number;           // 기본 타임아웃(ms)
  rdmaOperationTimeoutMs: number;     // RDMA 작업 타임아웃
  semanticSyncTimeoutMs: number;      // Semantic Sync 타임아웃
  healthCheckTimeoutMs: number;       // 헬스 체크 타임아웃
}

/**
 * TimeoutManager: 타임아웃 표준화
 *
 * 역할:
 * - 통일된 타임아웃 정책 제공
 * - 작업별 타임아웃 설정
 * - 타임아웃 초과 감지
 */
export class TimeoutManager {
  private readonly policy: TimeoutPolicy;

  constructor(policy?: Partial<TimeoutPolicy>) {
    this.policy = {
      defaultTimeoutMs: policy?.defaultTimeoutMs ?? 5000,
      rdmaOperationTimeoutMs: policy?.rdmaOperationTimeoutMs ?? 3000,
      semanticSyncTimeoutMs: policy?.semanticSyncTimeoutMs ?? 7000,
      healthCheckTimeoutMs: policy?.healthCheckTimeoutMs ?? 2000,
    };
  }

  /**
   * 타임아웃이 있는 작업 실행
   * @param operation 실행할 작업
   * @param timeoutMs 타임아웃(ms), 기본값: defaultTimeoutMs
   * @returns 작업 결과
   */
  public async executeWithTimeout<T>(
    operation: () => Promise<T>,
    timeoutMs?: number
  ): Promise<T> {
    const timeout = timeoutMs ?? this.policy.defaultTimeoutMs;

    return Promise.race([
      operation(),
      new Promise<T>((_, reject) =>
        setTimeout(
          () => reject(new Error(`Operation timeout after ${timeout}ms`)),
          timeout
        )
      ),
    ]);
  }

  /**
   * RDMA 작업 타임아웃 실행
   */
  public async executeRDMAWithTimeout<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.executeWithTimeout(operation, this.policy.rdmaOperationTimeoutMs);
  }

  /**
   * Semantic Sync 타임아웃 실행
   */
  public async executeSyncWithTimeout<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.executeWithTimeout(operation, this.policy.semanticSyncTimeoutMs);
  }

  /**
   * 헬스 체크 타임아웃 실행
   */
  public async executeHealthCheckWithTimeout<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.executeWithTimeout(operation, this.policy.healthCheckTimeoutMs);
  }

  /**
   * 타임아웃 정책 조회
   */
  public getPolicy(): TimeoutPolicy {
    return { ...this.policy };
  }
}

/**
 * AutoRecoveryOrchestrator: 자동 복구 오케스트레이터
 *
 * Circuit Breaker + Retry Strategy + Timeout Manager를 조합
 */
export class AutoRecoveryOrchestrator {
  private circuitBreaker: CircuitBreaker;
  private retryStrategy: RetryStrategy;
  private timeoutManager: TimeoutManager;

  constructor(
    circuitBreakerConfig?: CircuitBreakerConfig,
    retryPolicy?: RetryPolicy,
    timeoutPolicy?: Partial<TimeoutPolicy>
  ) {
    this.circuitBreaker = new CircuitBreaker(
      circuitBreakerConfig ?? {
        failureThreshold: 5,
        successThreshold: 2,
        timeout: 10000,
        monitoringWindow: 60000,
      }
    );

    this.retryStrategy = new RetryStrategy(
      retryPolicy ?? {
        maxRetries: 3,
        initialDelayMs: 100,
        maxDelayMs: 10000,
        backoffMultiplier: 2,
        jitterFactor: 0.1,
      }
    );

    this.timeoutManager = new TimeoutManager(timeoutPolicy);
  }

  /**
   * 완전한 복구 메커니즘으로 작업 실행
   * 1. Circuit Breaker 확인
   * 2. 재시도 with 지수 백오프
   * 3. 타임아웃 보호
   */
  public async executeWithFullRecovery<T>(
    operation: () => Promise<T>,
    timeoutMs?: number
  ): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      return this.retryStrategy.execute(async () => {
        return this.timeoutManager.executeWithTimeout(operation, timeoutMs);
      });
    });
  }

  /**
   * RDMA 작업 전용
   */
  public async executeRDMAWithRecovery<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      return this.retryStrategy.execute(async () => {
        return this.timeoutManager.executeRDMAWithTimeout(operation);
      });
    });
  }

  /**
   * Semantic Sync 작업 전용
   */
  public async executeSyncWithRecovery<T>(
    operation: () => Promise<T>
  ): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      return this.retryStrategy.execute(async () => {
        return this.timeoutManager.executeSyncWithTimeout(operation);
      });
    });
  }

  /**
   * 상태 조회
   */
  public getStatus(): {
    circuitBreaker: CircuitBreakerMetrics;
    retryCount: number;
    timeoutPolicy: TimeoutPolicy;
  } {
    return {
      circuitBreaker: this.circuitBreaker.getMetrics(),
      retryCount: this.retryStrategy.getRetryCount(),
      timeoutPolicy: this.timeoutManager.getPolicy(),
    };
  }

  /**
   * 상태 리셋
   */
  public reset(): void {
    this.circuitBreaker = new CircuitBreaker(
      this.circuitBreaker.getMetrics() as any
    );
  }
}

